    macro_rules! ld64 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r64, u64, $a, $dst, $pc, $ic, $rem) }; }
