    pub mod region {
    // Region 7 of tie_proc (0x282218), 0x28289c..0x282928, SPEED STYLE (S2e) + RELOCATABLE FORM (every pc is fr.pc(OFF), no level constants).
    // GPRs in u64 locals, VU0 maths via hs_fast::vu0 (one live Chop), flags only at the exit (last flag op = vmaddx.y, dest y),
    // sticky bits 6-7 only if not both set at entry, every modified register written back at every exit (flush!).
    use super::gen::*;
    use crate::cpu::Cpu;
    use crate::hs::{deopt, Frame};
    use crate::hs_fast::vu0::{st_of_mac, Chop, Sticky, V};
    use crate::hs_fast::{lo, sx32, wlo, Fm};
    
    pub fn region(c: &mut Cpu, fr: &Frame) -> bool {
        if c.pc != fr.pc(0x684) {
            return false;
        }
        if c.vi[16] & 0xc0 == 0xc0 { run::<false>(c, fr) } else { run::<true>(c, fr) }
    }
    
    #[inline(always)]
    fn run<const ST: bool>(c: &mut Cpu, fr: &Frame) -> bool {
        let fm = Fm::new(c);
        let lim = c.mem.limit;
        let mut ic = c.icount;
        let (mut at, mut v0, mut v1, mut a0) = (lo(c, 1), lo(c, 2), lo(c, 3), lo(c, 4));
        let (mut t7, mut s4) = (lo(c, 15), lo(c, 20));
        let s5 = lo(c, 21);
        let ra = lo(c, 31) as u32;
        let p0 = V::ld(c.vf[0]).prep();
        let p16 = V::ld(c.vf[16]).prep();
        let p18 = V::ld(c.vf[18]).prep();
        let p24 = V::ld(c.vf[24]).prep();
        let (e2, e3, e4) = (V::ld(c.vf[2]), V::ld(c.vf[3]), V::ld(c.vf[4]));
        let eacc = V::ld(c.vacc);
        let e16 = c.vi[16];
        let mut vf1 = V::ld(c.vf[1]);
        let mut sk = Sticky::new();
        let mut g = Chop::new(); // MXCSR = CSR_CHOP for the V ops; flush! ends it
        let (mut v2, mut v3, mut v4, mut acc, mut lv) = (e2, e3, e4, eacc, e2);
        let mut any1 = false;
        macro_rules! stk {
            ($m:literal, $v:expr) => {
                if ST {
                    sk.acc::<$m>($v);
                }
            };
        }
        // Write back EVERY register the region modified (idempotent; used before every exit and deopt).
        macro_rules! flush {
            () => {{
                g.end();
                c.icount = ic;
                wlo(c, 1, at);
                wlo(c, 2, v0);
                wlo(c, 3, v1);
                wlo(c, 4, a0);
                wlo(c, 15, t7);
                wlo(c, 20, s4);
                c.vf[1] = vf1.st();
                if any1 {
                    c.vf[2] = e2.blend::<7>(v2).st();
                    c.vf[3] = e3.blend::<1>(v3).st();
                    c.vf[4] = e4.blend::<2>(v4).st();
                    c.vacc = eacc.blend::<2>(acc).st();
                    let m = lv.mac(0x4);
                    c.vi[17] = m;
                    c.vi[16] = (e16 & !0xf) | st_of_mac(m) | if ST { sk.bits() << 6 } else { 0 };
                }
            }};
        }
        loop {
            // ---- block 0 @0x28289c: ld at,0x20(s4); addi s4,s4,0x20; beq s4,s5 (slot: lqc2 vf1,0(s4))
            if ic + 35 > lim {
                flush!();
                return deopt(c, fr, fr.pc(0x684), ic);
            }
            let ea = (s4 as u32).wrapping_add(0x20);
            let Some(q) = fm.r128(ea) else {
                flush!();
                return deopt(c, fr, fr.pc(0x684), ic);
            };
            let Some(dw) = fm.r64(ea) else {
                flush!();
                return deopt(c, fr, fr.pc(0x684), ic);
            };
            ic += T[0] as u64;
            s4 = sx32(ea);
            at = dw;
            vf1 = V::from_u128(q);
            if s4 == s5 {
                let _ = go!(c, fr, 0);
                return true;
            }
            let _ = go!(c, fr, 1);
            // ---- block 1 @0x2828ac: nop; beqz at,0x28289c (slot: lw t7,0x10(s4))
            let Some(w1) = fm.win::<0x14>(s4 as u32) else {
                flush!();
                return deopt(c, fr, fr.pc(0x694), ic);
            };
            ic += T[1] as u64;
            t7 = sx32(w1.r32::<0x10>());
            if at == 0 {
                let _ = go!(c, fr, 2);
                continue;
            }
            let _ = go!(c, fr, 3);
            // ---- block 2 @0x2828b8: vsuby.xyz vf2,vf16,vf1y; lbu v1,0x1b(s4); vmulw.x vf3,vf1,vf24w; lhu a0,0x1e(s4);
            //      vadda.y vf18,vf0; pref; vmaddx.y vf4,vf1,vf18x; nop; bnez v1 (slot: ori v1,zero,0xffff)
            let Some(w2) = fm.win::<0x20>(s4 as u32) else {
                flush!();
                return deopt(c, fr, fr.pc(0x6a0), ic);
            };
            ic += T[2] as u64;
            let p1 = vf1.prep();
            let r2 = p16.sub(p1.bcy());
            stk!(7, r2);
            let r3 = p1.mul(p24.bcw());
            stk!(1, r3);
            let rac = p18.add(p0);
            stk!(2, rac);
            let r4 = rac.prep().madd(p1, p18.bcx());
            stk!(2, r4);
            (v2, v3, v4, acc, lv, any1) = (r2, r3, r4, rac, r4, true);
            let v1c = w2.r8::<0x1b>() as u64;
            a0 = w2.r16::<0x1e>() as u64;
            v1 = 0xffff;
            if v1c != 0 {
                let _ = go!(c, fr, 4);
            } else {
                let _ = go!(c, fr, 5);
                // ---- block 3 @0x2828e0: beq v1,a0,EXIT (slot nop)
                ic += T[3] as u64;
                if v1 == a0 {
                    let _ = go!(c, fr, 6);
                    return true;
                }
                let _ = go!(c, fr, 7);
            }
            // ---- block 4 @0x2828e8: lw v1,0x3f0c(ra); lw v0,0x3f1c(ra); andi a0,s4,0xfff; add v1,v1,a0; sub v0,v1,v0;
            //      lw v1,0x3f18(ra); srl v0,v0,5; addi a0,ra,0x39fe; beq v1,a0,EXIT (slot nop)
            let Some(w4) = fm.win::<0x14>(ra.wrapping_add(0x3f0c)) else {
                flush!();
                return deopt(c, fr, fr.pc(0x6d0), ic);
            };
            ic += T[4] as u64;
            v1 = sx32(w4.r32::<0>());
            v0 = sx32(w4.r32::<0x10>());
            a0 = s4 & 0xfff;
            v1 = sx32((v1 as u32).wrapping_add(a0 as u32));
            v0 = sx32((v1 as u32).wrapping_sub(v0 as u32));
            v1 = sx32(w4.r32::<0xc>());
            v0 = sx32((v0 as u32) >> 5);
            a0 = sx32(ra.wrapping_add(0x39fe));
            if v1 == a0 {
                let _ = go!(c, fr, 8);
                return true;
            }
            let _ = go!(c, fr, 9);
            // ---- block 5 @0x282918: sh v0,0(v1); addi v1,v1,2; sw v1,0x3f18(ra); nop
            let ic0 = ic;
            ic += T[5] as u64;
            st16!(c, fr, fm, v1 as u32, v0 as u16, fr.pc(0x700), ic0 + 1, 3);
            v1 = sx32((v1 as u32).wrapping_add(2));
            st32!(c, fr, fm, ra.wrapping_add(0x3f18), v1 as u32, fr.pc(0x708), ic0 + 3, 1);
            let _ = go!(c, fr, 10);
            return true;
        }
    }
    }
