                    let ic0 = ic;
                    ic += T[1] as u64;
                    v4 = v4.blend::<2>(v4.min(r18.bcz())); // 1 vminiz.y vf4,vf4,vf18z
                    at = (at & HI) | 0x4380_0000u128; // 2 lui $at,0x4380
