                    s0 = sx32(s4 as u32); // 5 addi $s0,$s4,0
                    v3 = v3.blend::<7>(fl!(7, 0xe, p0.add(p0))); // 6 vadd.xyz vf3,vf0,vf0
                    v3 = v3.blend::<8>(r18.max(v4.bcy())); // 7 vmaxy.w vf3,vf18,vf4y
                    let x = ld32!(c, fr, fm, (s4 as u32).wrapping_add(8), 10, fr.pc(0x894), ic0 + 8, 4); // 8 lw $t2,8($s4)
                    g.begin();
                    t2 = sx32(x);
                    t4 = sx32((t4 as u32).wrapping_add(1)); // 9 addi $t4,$t4,1
