                    let z = t2 == 0; // 11 beqz $t2 (reads t2 after the lw)
                    st128!(c, fr, fm, (sp as u32).wrapping_add(0x40), at, fr.pc(0x8a4), ic0 + 12, 0); // 12 slot: sq $at,0x40($sp)
