                    // vadday.x ACC, vf12, vf12y
                    let r = fop!(1, 8, f12.prep().add(f12.prep().bcy()));
                    ac = ac.blend::<1>(r);
                    // vmaddz.x vf12, vf11, vf12z
                    let r = fop!(1, 8, ac.prep().madd(f11.prep(), f12.prep().bcz()));
                    f12 = f12.blend::<1>(r);
                    // vsubx.y vf0, vf9, vf12x (flags only: vf0 is never written)
                    let _r = fop!(2, 4, f9.prep().sub(f12.prep().bcx()));
