                    f5 = f5.blend::<1>(r);
                    // sll $a0, $a3, 1
                    s4!(sx32((r7 as u32) << 1));
                    // vaddw.y vf6, vf6, vf0w
                    let r = fop!(2, 4, f6.prep().add(p0.bcw()));
