                    // sll $v1, $a3, 7
                    r3 = sx32((r7 as u32) << 7);
                    // sll $a0, $a3, 2
                    s4!(sx32((r7 as u32) << 2));
                    // subu $v1, $v1, $a0
                    r3 = sx32((r3 as u32).wrapping_sub(r4 as u32));
                    // subu $v1, $v1, $a3
