                    s4!(sx32((r3 as u32) >> 1));
                    // andi $a0, $a0, 0xff
                    s4!((r4 as u64) & 0xff);
                    // addu $a0, $a0, $a2
                    s4!(sx32((r4 as u32).wrapping_add(r6 as u32)));
