                    let r = fop!(7, 0xe, ac.prep().madd(f6.prep(), f1.prep().bcy()));
                    ac = ac.blend::<7>(r);
                    // vmaddz.xyz vf1, vf7, vf1z
                    let r = fop!(7, 0xe, ac.prep().madd(f7.prep(), f1.prep().bcz()));
