                    let r = fop!(7, 0xe, f5.prep().mul(f3.prep().bcx()));
                    ac = ac.blend::<7>(r);
                    // vmadday.xyz ACC, vf6, vf3y
                    let r = fop!(7, 0xe, ac.prep().madd(f6.prep(), f3.prep().bcy()));
                    ac = ac.blend::<7>(r);
                    // vmaddz.xyz vf3, vf7, vf3z
